const payload = items[0]?.json?.body || items[0]?.json || {};
const required = ['company_name', 'exec_type', 'industry'];
const missing = required.filter((field) => !payload[field]);
const runId = payload.run_id || `dfa_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
const now = new Date().toISOString();
const state = {
  run_id: runId,
  created_at: now,
  updated_at: now,
  inputs: {
    company_name: payload.company_name || '',
    exec_type: payload.exec_type || '',
    industry: payload.industry || '',
    expert_pref: payload.expert_pref || 'pick_for_me',
    report_purpose: payload.report_purpose || 'sales_pitch',
    delivery_targets: payload.delivery_targets || [],
    human_review: payload.human_review ?? false,
    advanced_context: payload.advanced_context || {}
  },
  entity: null,
  research: { financials: {}, peers: [], news_events: [], market_data: {} },
  normalized: { periods: [], metrics: {}, gaps: [], reliability_map: {}, formulas: {} },
  sections: {},
  delivery: { status: missing.length ? 'clarification_required' : 'running' },
  audit_log: [{ timestamp: now, event_type: 'run_initialized', status: missing.length ? 'WARN' : 'OK', message: missing.length ? `Missing fields: ${missing.join(', ')}` : 'Run initialized' }]
};
return [{ json: { state, missing, proceed: missing.length === 0 } }];

const init = $('Initialize Run State').first().json;
const state = init.state;
const directory = items[0]?.json || {};
const rows = Array.isArray(directory) ? directory : Object.values(directory);
const normalize = (value) => String(value || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const inputName = state.inputs.company_name || '';
const inputTicker = state.inputs.advanced_context?.ticker || state.inputs.ticker || '';
const inputNorm = normalize(inputName);
const tickerNorm = normalize(inputTicker);
function score(row) {
  const title = row.title || row.name || '';
  const ticker = row.ticker || '';
  const titleNorm = normalize(title);
  const tickerValue = normalize(ticker);
  let points = 0;
  if (tickerNorm && tickerValue === tickerNorm) points += 100;
  if (titleNorm === inputNorm) points += 90;
  if (titleNorm.startsWith(inputNorm)) points += 70;
  if (titleNorm.includes(inputNorm)) points += 40;
  if (inputNorm.includes(titleNorm) && titleNorm.length > 3) points += 20;
  if (/\binc\.?$/i.test(title)) points += 5;
  return points;
}
const ranked = rows
  .filter((row) => row && (row.title || row.name) && (row.cik_str || row.cik))
  .map((row) => ({ row, score: score(row) }))
  .filter((entry) => entry.score > 0)
  .sort((a, b) => b.score - a.score);
const best = ranked[0]?.row || null;
const rawCik = best?.cik_str || best?.cik || null;
const cik = rawCik ? String(rawCik).replace(/\D/g, '').padStart(10, '0') : null;
const entityName = best?.title || best?.name || state.inputs.company_name;
state.entity = {
  legal_name: entityName,
  ticker: best?.ticker || null,
  cik,
  exchange: null,
  fiscal_year_end: null,
  reporting_currency: 'USD',
  is_public: Boolean(cik),
  confidence: cik && ranked[0].score >= 70 ? 'HIGH' : (cik ? 'MEDIUM' : 'LOW'),
  sources: [{ source_name: 'SEC Company Tickers Directory', source_url: 'https://www.sec.gov/files/company_tickers.json', source_date: new Date().toISOString(), confidence: cik && ranked[0].score >= 70 ? 'HIGH' : (cik ? 'MEDIUM' : 'LOW') }]
};
state.audit_log.push({ timestamp: new Date().toISOString(), event_type: 'entity_resolution', status: cik ? 'OK' : 'WARN', message: cik ? `Resolved ${entityName} (${state.entity.ticker || 'no ticker'}) CIK ${cik}` : 'No CIK found; public-company Phase 1 cannot fetch XBRL facts.' });
return [{ json: { state, entity: state.entity, company_facts_url: cik ? `https://data.sec.gov/api/xbrl/companyfacts/CIK${cik}.json` : 'https://www.sec.gov/files/company_tickers.json' } }];

const resolved = $('Resolve Entity').first().json;
const state = resolved.state;
const factsResponse = items[0]?.json || {};
const usGaap = factsResponse?.facts?.['us-gaap'] || {};
const sourceUrl = resolved.company_facts_url;
const now = new Date().toISOString();

function factCandidates(names) {
  for (const name of names) {
    const fact = usGaap[name];
    if (!fact?.units) continue;
    const units = fact.units.USD || fact.units.shares || fact.units['USD/shares'] || Object.values(fact.units)[0] || [];
    if (Array.isArray(units) && units.length) return { tag: name, units };
  }
  return null;
}
function annualSeries(names, unit = 'USD') {
  const candidate = factCandidates(names);
  if (!candidate) return [];
  const annualRows = candidate.units.filter((row) => row.val !== undefined && row.form === '10-K');
  const byEnd = annualRows.reduce((map, row) => {
    const key = row.end || `${row.fy}-${row.fp}-${row.frame || ''}`;
    const existing = map.get(key);
    if (!existing || String(row.filed || '') > String(existing.filed || '')) map.set(key, row);
    return map;
  }, new Map());
  return Array.from(byEnd.values())
    .map((row) => ({
      value: row.val,
      unit,
      period: row.frame || (row.fy ? `FY${row.fy}` : row.end),
      fiscal_label: row.fp || 'FY',
      source_name: `SEC EDGAR Company Facts:${candidate.tag}`,
      source_url: sourceUrl,
      source_date: row.filed || now,
      source_section: row.form || 'companyfacts',
      confidence: 'HIGH',
      notes: row.end || row.frame || ''
    }))
    .sort((a, b) => String(a.notes || a.period).localeCompare(String(b.notes || b.period)))
    .slice(-5);
}
function latest(series) { return series[series.length - 1] || null; }
function na(metric, reason) {
  state.normalized.gaps.push({ metric, reason, source: 'normalizer', timestamp: now });
  return { value: 'N/A', unit: '', period: 'latest', source_name: 'N/A', source_url: '', source_date: now, confidence: 'N/A', notes: reason };
}
function sourceCell(v) {
  if (!v || v.value === 'N/A') return `N/A (${v?.notes || 'not available'})`;
  const display = typeof v.value === 'number' ? Intl.NumberFormat('en-US', { maximumFractionDigits: 1 }).format(v.value) : v.value;
  return `${display} ${v.unit || ''} [${v.source_name}, ${v.source_date}]`;
}
const metrics = {
  revenue: annualSeries(['RevenueFromContractWithCustomerExcludingAssessedTax', 'Revenues', 'SalesRevenueNet']),
  operating_income: annualSeries(['OperatingIncomeLoss', 'IncomeLossFromContinuingOperationsBeforeIncomeTaxesExtraordinaryItemsNoncontrollingInterest']),
  net_income: annualSeries(['NetIncomeLoss', 'ProfitLoss']),
  operating_cash_flow: annualSeries(['NetCashProvidedByUsedInOperatingActivities', 'NetCashProvidedByUsedInOperatingActivitiesContinuingOperations']),
  capex: annualSeries(['PaymentsToAcquirePropertyPlantAndEquipment', 'PaymentsToAcquireProductiveAssets']),
  long_term_debt: annualSeries(['LongTermDebtAndFinanceLeaseObligationsNoncurrent', 'LongTermDebtNoncurrent', 'LongTermDebtAndFinanceLeaseObligationsCurrent']),
  diluted_eps: annualSeries(['EarningsPerShareDiluted'], 'USD/share'),
  diluted_shares: annualSeries(['WeightedAverageNumberOfDilutedSharesOutstanding', 'WeightedAverageNumberOfSharesOutstandingDiluted'], 'shares')
};
state.normalized.metrics = metrics;
state.normalized.periods = [...new Set(Object.values(metrics).flat().map((m) => m.period))].sort();
state.normalized.formulas = {
  fcf: 'Free cash flow = operating cash flow - capital expenditures',
  operating_margin: 'Operating margin = operating income / revenue'
};
state.normalized.reliability_map = { public_company_xbrl: state.entity?.cik ? 'HIGH' : 'LOW' };
const latestRevenue = latest(metrics.revenue) || na('revenue', 'No SEC XBRL revenue tag found.');
const latestOpIncome = latest(metrics.operating_income) || na('operating_income', 'No SEC XBRL operating income tag found.');
const latestNetIncome = latest(metrics.net_income) || na('net_income', 'No SEC XBRL net income tag found.');
const latestOcf = latest(metrics.operating_cash_flow) || na('operating_cash_flow', 'No SEC XBRL operating cash flow tag found.');
const latestCapex = latest(metrics.capex) || na('capex', 'No SEC XBRL capex tag found.');
const latestDebt = latest(metrics.long_term_debt) || na('long_term_debt', 'No SEC XBRL long-term debt tag found.');
const latestEps = latest(metrics.diluted_eps) || na('diluted_eps', 'No SEC XBRL diluted EPS tag found.');
let fcf = na('free_cash_flow', 'Requires both operating cash flow and capex.');
if (typeof latestOcf.value === 'number' && typeof latestCapex.value === 'number') {
  fcf = { ...latestOcf, value: latestOcf.value - latestCapex.value, source_name: `${latestOcf.source_name} + ${latestCapex.source_name}`, notes: 'Computed as operating cash flow minus capex.' };
}
let opMargin = na('operating_margin', 'Requires both revenue and operating income.');
if (typeof latestRevenue.value === 'number' && typeof latestOpIncome.value === 'number' && latestRevenue.value !== 0) {
  opMargin = { ...latestOpIncome, value: latestOpIncome.value / latestRevenue.value, unit: 'ratio', source_name: `${latestOpIncome.source_name} + ${latestRevenue.source_name}`, notes: 'Computed as operating income divided by revenue.' };
}
const markdown = `## Section 2: Financial Snapshot\n\n| Metric | Latest Available Value | Source | Reliability | Notes |\n|---|---:|---|---|---|\n| Revenue | ${sourceCell(latestRevenue)} | SEC Company Facts | ${latestRevenue.confidence} | Latest annual filing value |\n| Operating Income | ${sourceCell(latestOpIncome)} | SEC Company Facts | ${latestOpIncome.confidence} | GAAP where available |\n| Operating Margin | ${typeof opMargin.value === 'number' ? (opMargin.value * 100).toFixed(1) + '%' : sourceCell(opMargin)} | Computed from sourced values | ${opMargin.confidence} | ${opMargin.notes} |\n| Net Income | ${sourceCell(latestNetIncome)} | SEC Company Facts | ${latestNetIncome.confidence} | Latest annual filing value |\n| Operating Cash Flow | ${sourceCell(latestOcf)} | SEC Company Facts | ${latestOcf.confidence} | Latest annual filing value |\n| Capex | ${sourceCell(latestCapex)} | SEC Company Facts | ${latestCapex.confidence} | Latest annual filing value |\n| Free Cash Flow | ${sourceCell(fcf)} | Computed from sourced values | ${fcf.confidence} | ${fcf.notes} |\n| Long-Term Debt | ${sourceCell(latestDebt)} | SEC Company Facts | ${latestDebt.confidence} | Latest annual filing value |\n| Diluted EPS | ${sourceCell(latestEps)} | SEC Company Facts | ${latestEps.confidence} | Latest annual filing value |\n\n### Data Gaps\n${state.normalized.gaps.length ? state.normalized.gaps.map((gap) => `- ${gap.metric}: ${gap.reason}`).join('\n') : '- None detected in Phase 1 metrics.'}`;
state.sections.s2_snapshot = markdown;
state.delivery.status = 'phase_1_completed';
state.audit_log.push({ timestamp: now, event_type: 'section_generated', status: 'OK', message: 'Section 2 snapshot generated from normalized SEC data only.' });
return [{ json: { run_id: state.run_id, status: state.delivery.status, entity: state.entity, normalized: state.normalized, section_2_snapshot: markdown, state } }];
